\title{Convex-Hull Confinement and Log-Partition Bounds\\ for Softmax Self-Attention}
\author{Aristotle}
\date{2026-06-23}

\begin{document}
\maketitle

\begin{abstract}
We develop a rigorous, self-contained analysis of a single softmax self-attention head, viewed as a kernel smoother over a finite set of tokens. Modeling an attention head by a query vector $q \in \R^d$, key vectors $k_1,\dots,k_n \in \R^d$, and value vectors $v_1,\dots,v_n \in \R^m$, we define the unnormalized exponential kernel $\kappa(q,k)=\exp\inner{q}{k}$, the partition function $Z=\sum_j \kappa(q,k_j)$, the softmax attention weights $w_j=\kappa(q,k_j)/Z$, and the attention output $o_i=\sum_j w_j (v_j)_i$. We establish four principal results. First, the attention weights form a probability distribution: they are strictly positive and sum to one (\texttt{attnWeight\_sum\_one}). Second, a purely order-theoretic lemma shows that any convex combination of points contained in an interval $[\ell,h]$ remains in $[\ell,h]$ (\texttt{convexCombo\_mem\_Icc}). Third, combining these yields the \emph{confinement law}: every coordinate of the attention output lies in the interval, and hence the convex hull, spanned by the corresponding value coordinates (\texttt{attnOutput\_mem\_Icc}). Fourth, we prove a log-sum-exp lower bound stating that the log-partition function dominates every individual score (\texttt{logPartition\_ge\_term}). We discuss how these foundational facts underpin boundedness, robustness, the kernel-smoother interpretation, universal approximation, and the attention-sink phenomenon, and we outline a program of conjectures sharpening each direction.

\medskip
\noindent\textbf{Keywords:} softmax attention, kernel method, partition function, log-sum-exp, convex hull, probability simplex, transformers, sequence-to-sequence.
\end{abstract}

\section{Introduction}

The transformer architecture has become the dominant computational substrate of modern machine learning, and its central primitive is the \emph{self-attention} mechanism. Despite its empirical ubiquity, the basic mathematical properties of attention are often stated informally. The purpose of this paper is to isolate and prove, from first principles, the structural facts that make a single softmax attention head a \emph{well-behaved averaging operator}: its weights form a genuine probability distribution, its output is confined to the convex hull of its values, and its normalization constant obeys a sharp log-sum-exp lower bound.

Our viewpoint is that softmax attention is a \emph{kernel method}. The similarity kernel is the exponentiated inner product $\exp\inner{q}{k}$; the attention head is then a Nadaraya--Watson-style kernel smoother that reports a locally reweighted average of the value vectors. This perspective immediately suggests which classical guarantees ought to transfer---boundedness, continuity, hull confinement---and we make them precise here. All results below are fully formalized and machine-checked; we present the mathematical statements and proof sketches.

\subsection{Notation}
We fix natural numbers $d, n, m$ denoting respectively the query/key dimension, the number of tokens, and the value dimension. We index tokens by $j \in \{1,\dots,n\}$. Throughout, $\inner{x}{y} = \sum_i x_i y_i$ denotes the standard Euclidean inner product, and $[\ell, h]$ the closed real interval $\{t : \ell \le t \le h\}$. For results requiring at least one token we assume $n \ge 1$.

\section{The model}

\begin{definition}[Exponential kernel / score, \texttt{expKernel}]
For $q \in \R^d$ and $k \in \R^d$, the \emph{unnormalized exponential kernel} is
\[ \kappa(q,k) = \exp\!\Big(\textstyle\sum_{i} q_i\, k_i\Big) = \exp\inner{q}{k}. \]
\end{definition}

\begin{definition}[Partition function, \texttt{attnPartition}]
For keys $k_1,\dots,k_n$, the \emph{partition function} is
\[ Z(q,K) = \sum_{j} \kappa(q,k_j) = \sum_j \exp\inner{q}{k_j}. \]
\end{definition}

\begin{definition}[Softmax attention weight, \texttt{attnWeight}]
The \emph{attention weight} of token $j$ is the normalized kernel
\[ w_j(q,K) = \frac{\kappa(q,k_j)}{Z(q,K)} = \frac{\exp\inner{q}{k_j}}{\sum_{\ell}\exp\inner{q}{k_\ell}}. \]
\end{definition}

\begin{definition}[Attention output, \texttt{attnOutput}]
For values $v_1,\dots,v_n \in \R^m$, the \emph{attention output} has $i$-th coordinate
\[ o_i(q,K,V) = \sum_{j} w_j(q,K)\,(v_j)_i. \]
\end{definition}

This is the canonical single-head scaled-dot-product attention (with temperature folded into $q$), restricted to a single query; extending to multiple queries amounts to applying the construction row by row.

\section{Positivity and normalization}

\begin{lemma}[Kernel positivity, \texttt{expKernel\_pos}]
For all $q,k$, $\kappa(q,k) > 0$.
\end{lemma}
\begin{proof}
The real exponential is strictly positive.
\end{proof}

\begin{lemma}[Partition positivity, \texttt{attnPartition\_pos}]
If $n\ge 1$ then $Z(q,K) > 0$.
\end{lemma}
\begin{proof}
$Z$ is a sum, over a nonempty index set, of strictly positive terms.
\end{proof}

\begin{lemma}[Weight positivity, \texttt{attnWeight\_pos}, \texttt{attnWeight\_nonneg}]
If $n \ge 1$ then $w_j(q,K) > 0$ for every $j$, hence $w_j(q,K) \ge 0$.
\end{lemma}
\begin{proof}
A quotient of a positive numerator by a positive denominator is positive.
\end{proof}

\begin{theorem}[Weights form a probability distribution, \texttt{attnWeight\_sum\_one}]
If $n \ge 1$ then $\sum_{j} w_j(q,K) = 1$.
\end{theorem}
\begin{proof}
Each weight shares the denominator $Z=\sum_\ell \kappa(q,k_\ell)$. Pulling it out,
\[ \sum_j \frac{\kappa(q,k_j)}{Z} = \frac{\sum_j \kappa(q,k_j)}{Z} = \frac{Z}{Z} = 1, \]
where the last equality uses $Z\neq 0$, valid since $Z>0$.
\end{proof}

Thus $(w_j)_j$ lies in the open probability simplex $\Delta^{n-1} = \{ w : w_j \ge 0,\ \sum_j w_j = 1\}$.

\section{The confinement law}

\begin{lemma}[Convex combinations preserve intervals, \texttt{convexCombo\_mem\_Icc}]
Let $\ell, h \in \R$, let $w_1,\dots,w_n \ge 0$ with $\sum_j w_j = 1$, and let $x_1,\dots,x_n \in [\ell, h]$. Then $\sum_{j} w_j x_j \in [\ell, h]$.
\end{lemma}
\begin{proof}
For the lower bound, $w_j \ge 0$ and $x_j \ge \ell$ give $\sum_j w_j x_j \ge \sum_j w_j \ell = \ell\sum_j w_j = \ell$. The upper bound is symmetric, using $x_j \le h$. Both steps factor the constant out of the sum and use $\sum_j w_j = 1$.
\end{proof}

\begin{theorem}[Convex-hull confinement, \texttt{attnOutput\_mem\_Icc}]
Fix a coordinate $i$ and suppose $\ell \le (v_j)_i \le h$ for every token $j$. If $n \ge 1$, then $o_i(q,K,V) \in [\ell, h]$.
\end{theorem}
\begin{proof}
By definition $o_i = \sum_j w_j (v_j)_i$. Apply the previous lemma with weights $w_j(q,K)$ (non-negative and summing to one by the results of Section 3) and points $x_j=(v_j)_i \in [\ell,h]$.
\end{proof}

\begin{corollary}[Hull confinement]
Applying the theorem coordinatewise with $\ell=\min_j (v_j)_i$ and $h=\max_j (v_j)_i$ shows the output lies in the convex hull $\conv\{v_1,\dots,v_n\} = \{\sum_j w_j v_j : w \in \Delta^{n-1}\}$, since $o=\sum_j w_j v_j$ is by construction a convex combination of the values.
\end{corollary}

\noindent\textbf{Interpretation.} The confinement law is the rigorous form of ``attention smooths rather than extrapolates.'' It yields (i) numerical stability---bounded values give bounded outputs with no amplification; (ii) robustness---continuous dependence on the values, with the output unable to leave the hull; (iii) kernel-smoother semantics---the head is a Nadaraya--Watson estimator and the output lies in the convex hull of the data.

\section{The log-partition bound}

\begin{theorem}[Log-partition dominates each score, \texttt{logPartition\_ge\_term}]
If $n \ge 1$ then, for every token $j$,
\[ \log Z(q,K) \ge \inner{q}{k_j} = \sum_i q_i (k_j)_i. \]
\end{theorem}
\begin{proof}
Write $Z = \sum_\ell \exp\inner{q}{k_\ell}$. Every summand is non-negative, so $Z \ge \exp\inner{q}{k_j}$. Since $Z>0$ and $\log$ is monotone with $\log(\exp t)=t$, applying $\log$ yields $\log Z \ge \inner{q}{k_j}$ (equivalently, $\log Z \ge t \iff e^t \le Z$ with $t=\inner{q}{k_j}$).
\end{proof}

\noindent\textbf{Interpretation.} Writing $w_j = \exp(\inner{q}{k_j} - \log Z)$, the theorem forces the exponent $\le 0$, so $w_j \le 1$. When one score dominates by margin $g$, its term dominates $Z$, forcing $w_{j^\star}\to 1$: attention focuses. The same inequality justifies the max-subtraction trick for numerically stable softmax.

\section{Algorithms}

\paragraph{Stable softmax attention (via log-sum-exp).}
Given $q$, keys $K$, values $V$: (1) compute scores $z_j = \inner{q}{k_j}$; (2) compute $z^\star=\max_j z_j$; (3) compute $e_j=\exp(z_j-z^\star)$; (4) compute $S=\sum_j e_j$ and $\log Z = z^\star + \log S$; (5) compute $w_j=e_j/S$; (6) compute $o=\sum_j w_j v_j$. The weights sum to one (Theorem on \texttt{attnWeight\_sum\_one}), and the output lies in the per-coordinate range of $V$ (confinement). Time complexity $O(nd+nm)$, space $O(n+m)$.

\paragraph{Confinement certificate.}
Compute $\ell_i=\min_j (v_j)_i$, $h_i=\max_j (v_j)_i$, run the procedure above, and verify $\ell_i \le o_i \le h_i$ for all $i$; in exact arithmetic this never fails.

\section{Applications and discussion}

\textbf{Bounded deep stacks.} Confinement supplies the attention-layer half of any boundedness argument: bounded values yield bounded outputs.

\textbf{Universal approximation, foreshadowed.} Softmax weights can be steered to any interior point of $\Delta^{n-1}$, so $o=\sum_j w_j v_j$ can approximate any point of the open convex hull of the values; with a covering argument on the simplex this gives approximation of sequence-to-sequence maps to arbitrary accuracy, with logit magnitude $O(\log(1/\varepsilon))$.

\textbf{The attention sink.} If a token has logit gap $g$ over each of $n-1$ rivals, then $Z = e^{z}(1 + (n-1)e^{-g})$ and the sink mass is $1/(1+(n-1)e^{-g})$, which is $\Omega(1)$ as $n\to\infty$ precisely when $g \gtrsim \log n$.

\textbf{Kernel methods.} Identifying $\kappa(q,k)=\exp\inner{q}{k}$ as a similarity kernel places attention within the theory of kernel smoothers and reproducing-kernel methods.

\section{Worked examples and quantitative remarks}

\paragraph{A two-token head.} Let $d=1$, $n=2$, $m=1$, with $q=(\beta)$, keys $k_1=(0)$, $k_2=(1)$, values $v_1=(0)$, $v_2=(1)$. Then $Z=1+e^\beta$, $w_1=1/(1+e^\beta)$, $w_2=e^\beta/(1+e^\beta)$ (the logistic sigmoid), and $o=\sigma(\beta)\in(0,1)$. Theorem on \texttt{attnWeight\_sum\_one} is $w_1+w_2=1$; confinement is $\sigma(\beta)\in[0,1]$ (the open interior is reached but not the endpoints); the log-partition bound is $\log(1+e^\beta)\ge\beta$ and $\ge 0$.

\paragraph{Temperature and sharpening.} Replacing $q$ by $\beta q$ scales all scores by $\beta$. As $\beta\to\infty$ the largest-score weight tends to $1$ (focus); as $\beta\to 0$ the weights tend to uniform $1/n$ and the output to the centroid $\frac1n\sum_j v_j$. Confinement holds throughout: the reachable outputs trace the open convex hull as $q,\beta$ vary.

\paragraph{The hull is reached, not merely contained.} For any target $w^\star$ in the open simplex, choosing logits $z_j=\log w^\star_j$ gives $\mathrm{softmax}(z)=w^\star$, realizable as inner products for keys in general position. Hence the reachable set of a single head is \emph{exactly} the open convex hull of its values.

\section{Structural properties and the kernel viewpoint}

\paragraph{Shift invariance.} Adding a constant $c$ to all scores leaves the weights unchanged, since $e^{z_j+c}/\sum_\ell e^{z_\ell+c} = e^{z_j}/\sum_\ell e^{z_\ell}$. This justifies the max-subtraction trick and shows row-additive constants in the logit matrix are invisible to softmax.

\paragraph{Monotone response.} The Jacobian $\partial w_j/\partial z_\ell = w_j(\delta_{j\ell}-w_\ell)$ has positive diagonal and negative off-diagonal, so raising a token's score diverts mass toward it from all competitors---the mechanism that lets a sink token retain its advantage.

\paragraph{Nadaraya--Watson estimator.} With $\kappa(q,k)=\exp\inner{q}{k}$, the output is the kernel regression estimate $o = (\sum_j \kappa(q,k_j) v_j)/(\sum_j \kappa(q,k_j))$, and confinement is the classical fact that a kernel-weighted average of responses lies in their convex hull.

\paragraph{Log-partition as free energy.} $\log Z$ is the cumulant generating function of the scores: $\nabla_z \log Z = w$ and its Hessian is the covariance of the induced distribution. Convexity of log-sum-exp explains the smooth interpolation between the hard maximum ($\beta\to\infty$) and the soft average.

\section{Future directions}
\begin{enumerate}
  \item \textbf{Sharp threshold for the attention sink:} $\Omega(1)$ mass uniformly in $n$ iff $g(n)\ge \log n - O(1)$; vanishing for $g(n)=\log n - \omega(1)$.
  \item \textbf{Entropy law of attention concentration:} $H(\mathrm{softmax}\,z)$ is maximized ($=\log n$) at uniform logits and decreases monotonically with the maximal gap; $H\to 0$ iff one gap $\to\infty$.
  \item \textbf{Exact rank characterization:} $\rank(A)=1$ iff the logit matrix has identical rows up to additive row-constants; in general $\rank(A) \le \rank(\exp\circ Z)$.
  \item \textbf{Quantitative universal approximation:} for any measurable selection of convex combinations of a fixed value set and any $\varepsilon>0$, keys/queries exist with output within $\varepsilon$ in sup norm and logit magnitude $O(\log(1/\varepsilon))$.
\end{enumerate}

\section{Conclusion}
We have given a clean, fully verified account of the foundational properties of softmax self-attention: its weights are a probability distribution (\texttt{attnWeight\_sum\_one}), its output is confined to the convex hull of the values (\texttt{attnOutput\_mem\_Icc}, via \texttt{convexCombo\_mem\_Icc}), and its log-partition function dominates every score (\texttt{logPartition\_ge\_term}). These facts jointly characterize attention as a disciplined yet expressive averaging operator---a learnable kernel smoother that can focus sharply or blend broadly, but can never color outside the lines of its inputs.

